-- H2 projections for Phase 7.1/7.2 (V5 + V20).
CREATE TABLE conversations(id BIGINT PRIMARY KEY,campus_id BIGINT,type VARCHAR(32),title VARCHAR(128),context_type VARCHAR(32),context_id BIGINT,participant_key VARCHAR(64) DEFAULT '',access_revoked_at TIMESTAMP,created_by BIGINT,version INT DEFAULT 0,created_at TIMESTAMP,updated_at TIMESTAMP,UNIQUE(campus_id,context_type,context_id,participant_key));
CREATE TABLE conversation_members(id BIGINT PRIMARY KEY,conversation_id BIGINT,user_id BIGINT,unread_count INT DEFAULT 0,last_read_message_id BIGINT,last_read_at TIMESTAMP,created_at TIMESTAMP,UNIQUE(conversation_id,user_id));
CREATE TABLE messages(id BIGINT PRIMARY KEY,conversation_id BIGINT,sender_id BIGINT,content VARCHAR(4000),status VARCHAR(32) DEFAULT 'sent',client_message_id VARCHAR(64),created_at TIMESTAMP,UNIQUE(conversation_id,sender_id,client_message_id));
CREATE TABLE notifications(id BIGINT PRIMARY KEY,campus_id BIGINT,user_id BIGINT,type VARCHAR(32),title VARCHAR(128),content VARCHAR(512),target_type VARCHAR(32),target_id BIGINT,read_at TIMESTAMP,dedup_key VARCHAR(64) UNIQUE,created_at TIMESTAMP);
CREATE TABLE subscription_authorizations(id BIGINT PRIMARY KEY,user_id BIGINT,template_id VARCHAR(128),scene VARCHAR(64),status VARCHAR(32) DEFAULT 'granted',version INT DEFAULT 0,granted_at TIMESTAMP,revoked_at TIMESTAMP,created_at TIMESTAMP,UNIQUE(user_id,template_id,scene));
CREATE TABLE message_send_records(id BIGINT PRIMARY KEY,user_id BIGINT,channel VARCHAR(32),template_id VARCHAR(128),content_json VARCHAR(4000),dedup_key VARCHAR(64) UNIQUE,result VARCHAR(32) DEFAULT 'pending',error VARCHAR(512),retry_count INT DEFAULT 0,next_retry_at TIMESTAMP,created_at TIMESTAMP);
